import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第五卦 需 水天需 坎上乾下","description":"周易 - 第五卦 需 水天需 坎上乾下","frontmatter":{"title":"第五卦 需 水天需 坎上乾下","description":"周易 - 第五卦 需 水天需 坎上乾下"},"headers":[],"relativePath":"zh/classics/zhouyi/006.md","filePath":"zh/classics/zhouyi/006.md"}'),l={name:"zh/classics/zhouyi/006.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="需" tabindex="-1">需 <a class="header-anchor" href="#需" aria-label="Permalink to “需”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>有孚，光亨，贞吉。利涉大川。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>需，须也；险在前也。刚健而不陷，其义不困穷矣。需有孚，光亨，贞吉。位乎天位，以正中也。利涉大川，往有功也。</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>云上於天，需；君子以饮食宴乐。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>需 于郊。利用恒，无咎。象曰：需于郊，不犯难行也。利用恒，无咎；未失常也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>需于沙。小有言，终吉。象曰：需于沙，衍在中也。虽小有言，以终吉也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>需于泥，致寇至。象曰：需于泥，灾在外也。自我致寇，敬慎不败也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>需于血，出自穴。象曰：需于血，顺以听也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>需于酒食，贞吉。象曰：酒食贞吉，以中正也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>入于穴，有不速之客三人 来，敬之终吉。象曰：不速之客来，敬之终吉。虽不当位，未大失也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
